/**
 * The single error type for @takk/bayesroute.
 *
 * Every failure raised by the library is a {@link BayesRouteError} carrying a stable, machine-readable
 * {@link BayesRouteErrorCode}. Callers branch on `error.code`, never on message text.
 *
 * @packageDocumentation
 */

/** Stable, machine-readable error codes. Branch on these, not on message strings. */
export type BayesRouteErrorCode =
  | 'ERR_INVALID_INPUT'
  | 'ERR_INVALID_PRIOR'
  | 'ERR_NO_ARMS'
  | 'ERR_NOT_FOUND'
  | 'ERR_INVALID_AUDIT'
  | 'ERR_NUMERIC';

/** The single error type thrown across the whole library. */
export class BayesRouteError extends Error {
  readonly code: BayesRouteErrorCode;
  readonly details?: Readonly<Record<string, unknown>>;

  constructor(
    code: BayesRouteErrorCode,
    message: string,
    details?: Readonly<Record<string, unknown>>,
  ) {
    super(message);
    this.name = 'BayesRouteError';
    this.code = code;
    if (details !== undefined) {
      this.details = details;
    }
    Object.setPrototypeOf(this, BayesRouteError.prototype);
  }
}

/** Type guard for {@link BayesRouteError}. */
export function isBayesRouteError(value: unknown): value is BayesRouteError {
  return value instanceof BayesRouteError;
}
