/**
 * The query classifier.
 *
 * Routing is per (model, domain), so every query must be assigned a domain before the sampler runs.
 * The classifier is a pure function from query features to a domain label. The default honors an
 * explicit `domain` and otherwise falls back to a single shared domain; a keyword classifier matches
 * query text against per-domain keyword lists; a static classifier pins every query to one domain.
 * Any custom function is accepted, so a consumer can plug in an embedding or model-based router.
 *
 * @packageDocumentation
 */

import { BayesRouteError } from '../errors.js';
import type { QueryClassifier, QueryFeatures } from '../types.js';

export type { QueryClassifier, QueryFeatures } from '../types.js';

/** The domain used when nothing more specific is known. */
export const DEFAULT_DOMAIN = 'default';

/** Per-domain keyword lists. A query is assigned to the first domain whose keyword it contains. */
export type KeywordRules = Readonly<Record<string, ReadonlyArray<string>>>;

/** The default classifier: return an explicit `domain` if present, otherwise {@link DEFAULT_DOMAIN}. */
export function defaultClassifier(features: QueryFeatures): string {
  return features.domain ?? DEFAULT_DOMAIN;
}

/** A classifier that pins every query to a single fixed domain. */
export function staticClassifier(domain: string): QueryClassifier {
  if (domain.length === 0) {
    throw new BayesRouteError('ERR_INVALID_INPUT', 'staticClassifier requires a non-empty domain');
  }
  return () => domain;
}

/**
 * A classifier that matches the lowercased query text against per-domain keyword lists. An explicit
 * `domain` on the features always wins; otherwise the first domain with a matching keyword is used,
 * falling back to `fallback` when nothing matches.
 */
export function keywordClassifier(
  rules: KeywordRules,
  fallback: string = DEFAULT_DOMAIN,
): QueryClassifier {
  const compiled: ReadonlyArray<readonly [string, ReadonlyArray<string>]> = Object.entries(
    rules,
  ).map(
    ([domain, keywords]) => [domain, keywords.map((keyword) => keyword.toLowerCase())] as const,
  );
  return (features: QueryFeatures): string => {
    if (features.domain !== undefined) {
      return features.domain;
    }
    const text = (features.text ?? '').toLowerCase();
    if (text.length > 0) {
      for (const [domain, keywords] of compiled) {
        for (const keyword of keywords) {
          if (keyword.length > 0 && text.includes(keyword)) {
            return domain;
          }
        }
      }
    }
    return fallback;
  };
}
